// Catálogo de ejemplo: un producto por modelo 3D fotografiado (herramientas/fotos), y una segunda línea
// (otra marca, otros colores, otro precio) donde el modelo tiene variantes de color.
// Todo es ficticio: marcas, precios y especificaciones. Precios en USD, sin impuestos.
//
// p(modelo, subcategoría, 'nombre es|nombre pt|name en', precio USD, atributos, opciones)
//   opciones.co      color original del modelo (clave de herramientas/fotos/colores.json)
//   opciones.cond    'reacondicionado' | 'usado' (los modelos con desgaste a la vista)
//   opciones.g       garantía en meses
//   opciones.b       segunda línea: { n?, usd, a? } (se arma con la mitad de los colores)
//   opciones.tallas  variantes de talle/medida (sin foto propia)

export type Valor = string | number | boolean
export type Entrada = {
  m: string
  sub: string
  n: [string, string, string]
  usd: number
  a: Record<string, Valor>
  co?: string
  cond?: 'reacondicionado' | 'usado'
  g?: number
  b?: { n?: [string, string, string]; usd: number; a?: Record<string, Valor> }
  tallas?: { clave: string; valores: string[] }
}

type Opciones = Omit<Entrada, 'm' | 'sub' | 'n' | 'usd' | 'a' | 'b'> & { b?: { n?: string; usd: number; a?: Record<string, Valor> } }

const partir = (s: string) => s.split('|').map((x) => x.trim()) as [string, string, string]

function p(m: string, sub: string, n: string, usd: number, a: Record<string, Valor> = {}, o: Opciones = {}): Entrada {
  const { b, ...resto } = o
  return { m, sub, n: partir(n), usd, a, ...resto, ...(b ? { b: { ...b, n: b.n ? partir(b.n) : undefined } } : {}) }
}

